 private const string Owner="fixture:zhang-qi-ying-owner",Driver="fixture:zhang-qi-ying-driver",Quiet="fixture:zhang-qi-ying-quiet",Mode="identity:classic-zhang-qi-ying";
 private static readonly PlayerMarkerKind[] Tokens=[PlayerMarkerKind.Ziwei,PlayerMarkerKind.Houtu,PlayerMarkerKind.Yuqing,PlayerMarkerKind.Gouchen];
 public static void ActualFourTokensDiscardSuitsAndSourceLifetimeCold()
 {
  var(g,r)=Start();Play(g);Need(Tokens.All(m=>Count(g,m)==1),"Real gameStarting grants each binary token once.");var hp=V(g,1).Hp;Use(g,"damage",[1]);Reach(g,()=>Offer(g,"ol:zhenyi"));Activate(g);Play(g);Need(V(g,1).Hp==hp-2&&Count(g,PlayerMarkerKind.Yuqing)==0&&E<ZhenyiDamageIncreasedEvent>(g).Count()==1,"Actual source damage spends one Yuqing for precisely +1 without a judgment.");g=Cold(g,r);Use(g,"dump",[]);Play(g);Need(Count(g,PlayerMarkerKind.Yuqing)==1&&Tokens.All(m=>Count(g,m)<=1),"True native whole-hand discard regains its Heart token and never stacks binary marks.");Use(g,"remove",[]);Play(g);Need(Tokens.All(m=>Count(g,m)==1)&&!V(g,0).Skills!.Any(s=>s.ContentId=="ol:falu"),"Losing the source neither clears nor reinitializes existing role tokens.");_=Cold(g,r);
 }
 private static int Count(GameEngine g,PlayerMarkerKind m)=>V(g,0).Markers?.SingleOrDefault(x=>x.Kind==m)?.Count??0;
 private static PlayerSnapshot V(GameEngine g,int seat)=>g.CreateSnapshot(seat).Players[seat];
 private static IEnumerable<T>E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>();
 private static PendingDecision?P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
 private static bool Offer(GameEngine g,string skill)=>P(g)?.SkillPrompt?.SkillId==skill&&P(g)!.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate")||P(g)?.Kind==DecisionKind.ProgramJudgmentTrigger&&g.ResolutionStack.OfType<ProgramJudgmentTriggerWindowFrame>().LastOrDefault()is{ZhenyiBeforeResult:true}j&&j.CandidateIndex<j.Candidates.Count&&j.Candidates[j.CandidateIndex].SkillId==skill&&P(g)!.Choices.Any(c=>c.Parameters.GetValueOrDefault("action")=="program-judgment-trigger-activate");
 private static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m+" ");}
 private static void Accept(GameEngine g,GameCommand c){var a=g.Submit(c);Need(a.Accepted,(a.Error?.Message??"Rejected native Zhang Qi Ying command.")+" "+JsonSerializer.Serialize(new{g.State,Pending=P(g),Stack=g.ResolutionStack.Select(f=>new{Type=f.GetType().Name,f.Id}),Recent=g.Events.TakeLast(12).Select(e=>new{Type=e.Payload.GetType().Name,Fact=JsonSerializer.Serialize(e.Payload,e.Payload.GetType())})}));}
 private static void Answer(GameEngine g,Func<PromptChoice,bool>choose){var p=P(g)!;Need(p.PlayerSeat==0,"Only the actual human answers this fixture.");Accept(g,new AnswerPromptCommand(0,p.PromptId,p.Choices.First(choose).Id,g.Revision));}
 private static void Activate(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate"||c.Parameters.GetValueOrDefault("action")=="program-judgment-trigger-activate");
 private static void Use(GameEngine g,string id,IReadOnlyList<int>targets)=>Accept(g,new UseProgramSkillCommand(0,Driver,id,[],targets,g.Revision,P(g)!.PromptId));
 private static void End(GameEngine g)=>Accept(g,new EndPlayPhaseCommand(0,g.Revision,P(g)!.PromptId));
 private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
 private static void Reach(GameEngine g,Func<bool>done)
 {for(var i=0;i<200;i++){if(done())return;var p=P(g);if(p is{PlayerSeat:0}&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip"))Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");else if(p is{PlayerSeat:0,Kind:DecisionKind.RescueDying or DecisionKind.RespondDodge or DecisionKind.RespondSlash or DecisionKind.Nullification})Answer(g,c=>c.Parameters.GetValueOrDefault("response")is"pass"or"take-damage"or"let-die");else if(p is{PlayerSeat:0,Kind:DecisionKind.PlayCard})End(g);else Accept(g,new AdvanceOneStepCommand(g.Revision));}throw new InvalidOperationException("Zhang Qi Ying boundary missing: "+JsonSerializer.Serialize(new{Pending=P(g),Stack=g.ResolutionStack,Players=Enumerable.Range(0,4).Select(s=>V(g,s))}));}
 private static string State(GameEngine g)=>JsonSerializer.Serialize(new{Views=Enumerable.Range(0,4).Select(s=>SnapshotJson.Serialize(g.CreateSnapshot(s))),Frames=g.ResolutionStack.Select(f=>JsonSerializer.Serialize(f,f.GetType())),g.CardMovements});
 private static GameEngine Cold(GameEngine g,ContentRegistry r){var cold=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(g.CreateCheckpoint())),r);Need(State(g)==State(cold),"Native private views, exact original materials and typed paid children survive cold commands.");return cold;}
 private static(GameEngine,ContentRegistry)Start(bool watch=false,bool rescue=false,bool grain=false,bool bagua=false)
 {var r=ContentRegistry.Build(new StandardContentPackage(),new Fixture(watch,rescue,grain,bagua));var g=GameEngine.CreateStandard(new GameOptions{Seed=7,PlayerCount=4,HumanSeat=0,HumanRole=Role.Lord,ModeId=Mode,UseInteractiveSetup=true,AdvanceAfterHumanCommands=false,UseInteractiveDiscard=false,MaxTurns=12},r);Accept(g,new StartGameCommand());Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.SelectGeneral});Accept(g,new SelectGeneralCommand(0,Owner,g.Revision,P(g)!.PromptId));return(g,r);}
